/// Told apart by `_tag`; switch over the subclasses.
sealed class Phase {
  const Phase();

  factory Phase.fromJson(Map<String, dynamic> j) => switch (j['_tag']) {
    'arriving' => PhaseArriving.fromJson(j),
    'working' => PhaseWorking.fromJson(j),
    'ripe' => PhaseRipe.fromJson(j),
    'failed' => PhaseFailed.fromJson(j),
    'resting' => PhaseResting.fromJson(j),
    'closed' => PhaseClosed.fromJson(j),
    final other => throw FormatException('Phase: unknown _tag', other),
  };

  Map<String, dynamic> toJson();
}

