/// The `manager` endpoints of VibeValleyApi.
class ManagerApi {
  ManagerApi._(this._api);
  final VibeValleyApi _api;

  Future<void> open() async {
    await _api._call('POST', '/api/v1/manager/open', query: {}, body: null);
  }

  /// Ends the manager's run under way and drops what waits for it; the sessions it sent keep working.
  Future<void> stop() async {
    await _api._call('POST', '/api/v1/manager/stop', query: {}, body: null);
  }

  /// The v1 caption relay without a call id is accepted only with one active call.
  Future<void> hear({required SayRequest body}) async {
    await _api._call('POST', '/api/v1/manager/hear', query: {}, body: body.toJson());
  }

  Future<ArchiveListing> listArchive({String? q}) async {
    final j = await _api._call('GET', '/api/v1/manager/archive', query: {if (q != null) 'q': '${q!}'}, body: null);
    return ArchiveListing.fromJson(j as Map<String, dynamic>);
  }

  Future<String> getArchive({required String name}) async {
    final j = await _api._call('GET', '/api/v1/manager/archive/${Uri.encodeComponent((name).toString())}', query: {}, body: null);
    return j as String;
  }

  /// Saves the turn begun at a step of the manager's log as a case for its evals, with what it should have done.
  Future<ManagerEval> markWrong({required ManagerEvalRequest body}) async {
    final j = await _api._call('POST', '/api/v1/manager/evals', query: {}, body: body.toJson());
    return ManagerEval.fromJson(j as Map<String, dynamic>);
  }
}

