    return Issue.fromJson(j as Map<String, dynamic>);
  }

  Future<void> delete({required String id}) async {
    await _api._call('DELETE', '/api/v1/issues/${Uri.encodeComponent((id).toString())}', query: {}, body: null);
  }

  Future<List<Issue>> move({required String id, required MoveIssueRequest body}) async {
    final j = await _api._call('PUT', '/api/v1/issues/${Uri.encodeComponent((id).toString())}/move', query: {}, body: body.toJson());
    return [for (final e in j as List) Issue.fromJson(e as Map<String, dynamic>)];
  }

  /// Moving an issue is what it does: todo sends it out (or waits for room), done merges, canceled sends its session home,
  /// todo again after a round or a close is another round with text. Issue.moves lists where it may go.
  Future<Issue> status({required String id, required IssueStatusRequest body}) async {
    final j = await _api._call('PUT', '/api/v1/issues/${Uri.encodeComponent((id).toString())}/status', query: {}, body: body.toJson());
    return Issue.fromJson(j as Map<String, dynamic>);
  }

  /// A session reads the code and writes the backlog issue to the issue's format (title, description, criteria), then
  /// leaves; with asks open, the word is their answer. The issue stays in the backlog until it is moved to todo.
  Future<Issue> draft({required String id, required IssueDraftRequest body}) async {
    final j = await _api._call('POST', '/api/v1/issues/${Uri.encodeComponent((id).toString())}/draft', query: {}, body: body.toJson());
    return Issue.fromJson(j as Map<String, dynamic>);
  }

  /// Starts a queued todo now, if its project and the farm have room; otherwise it keeps its place in the queue.
  Future<Dispatched> dispatch({required String id, required IssueDispatchRequest body}) async {
    final j = await _api._call('POST', '/api/v1/issues/${Uri.encodeComponent((id).toString())}/dispatch', query: {}, body: body.toJson());
    return Dispatched.fromJson(j as Map<String, dynamic>);
  }

  /// The acceptance of what was handed back (in review): a pass makes it ready to harvest, a fail adds weeds and sends
  /// another round.
  Future<Issue> accept({required String id, required IssueAcceptRequest body}) async {
    final j = await _api._call('POST', '/api/v1/issues/${Uri.encodeComponent((id).toString())}/accept', query: {}, body: body.toJson());
    return Issue.fromJson(j as Map<String, dynamic>);
  }
